<script setup lang="ts">import{computed,ref}from"vue";import{readXmltvFile,type XmltvDocument}from"@/domain/iptv/xmltv";import{matchEpgChannels}from"@/domain/iptv/epgMatching";import{clearEpg,loadEpg,saveEpg}from"@/domain/iptv/epgStore";import{iptvChannelRepository}from"@/domain/repositories";import type{IptvChannelRecord}from"@/types/records";const props=defineProps<{channels:IptvChannelRecord[]}>();const open=ref(false),loading=ref(false),error=ref(""),document=ref<XmltvDocument|null>(null),sourceName=ref(""),saved=ref(loadEpg());const matches=computed(()=>document.value?matchEpgChannels(props.channels,document.value.channels):[]);const exact=computed(()=>matches.value.filter(x=>x.kind==="exact").length),suggested=computed(()=>matches.value.filter(x=>x.kind==="name").length),missing=computed(()=>matches.value.filter(x=>x.kind==="none").length);async function read(event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;loading.value=true;error.value="";try{document.value=await readXmltvFile(file);sourceName.value=file.name}catch(c){error.value=c instanceof Error?c.message:String(c)}finally{loading.value=false}}async function apply(){if(!document.value)return;for(const m of matches.value){if(m.kind==="name"&&m.xmltv)await iptvChannelRepository.update(m.channel.id,{epg_id:m.xmltv.id})}const value={importedAt:new Date().toISOString(),sourceName:sourceName.value,document:document.value};saveEpg(value);saved.value=value}function remove(){clearEpg();saved.value=null;document.value=null}</script><template><button class="button button-secondary" type="button" @click="open=true">▤ EPG/XMLTV</button><Teleport to="body"><div v-if="open" class="dialog-backdrop" @click.self="open=false"><section class="dialog-panel" role="dialog" aria-modal="true" aria-labelledby="epg-title"><div class="dialog-header"><div><p class="eyebrow">IPTV</p><h2 id="epg-title">Importar EPG/XMLTV</h2></div><button class="icon-button" type="button" aria-label="Fechar EPG" @click="open=false">×</button></div><label class="form-field"><span>XMLTV (.xml ou .xml.gz)</span><input type="file" accept=".xml,.gz,application/xml,application/gzip" @change="read"/></label><p v-if="loading" aria-live="polite">A processar XMLTV…</p><div v-if="error" class="form-alert form-alert-error" role="alert">{{error}}</div><section v-if="document" aria-live="polite"><h3>Correspondência</h3><p>{{document.channels.length}} canais XMLTV · {{document.programmes.length}} programas</p><p><strong>{{exact}}</strong> exatos · <strong>{{suggested}}</strong> sugestões por nome · <strong>{{missing}}</strong> sem correspondência</p><button class="button button-primary" type="button" @click="apply">Guardar EPG e aplicar sugestões</button></section><section v-if="saved"><h3>EPG atual</h3><p>{{saved.sourceName}} · {{new Date(saved.importedAt).toLocaleString("pt-PT")}}</p><button class="button button-secondary" type="button" @click="remove">Limpar EPG local</button></section></section></div></Teleport></template>
